332	func clausesOf(sw *ast.SwitchStmt, fset *token.FileSet, path string) []caseClause {
333		var out []caseClause
334		for _, stmt := range sw.Body.List {
335			cc, ok := stmt.(*ast.CaseClause)
336			if !ok || len(cc.List) == 0 {
337				continue
338			}
339			var keys []string
340			for _, expr := range cc.List {
341				lit, ok := expr.(*ast.BasicLit)
342				if !ok || lit.Kind != token.STRING {
343					continue
344				}
345				value, err := strconv.Unquote(lit.Value)
346				if err != nil {
347					continue
348				}
349				keys = append(keys, value)
350			}
351			if len(keys) == 0 {
352				continue
353			}
354			position := fset.Position(cc.Pos())
355			out = append(out, caseClause{
356				where: filepath.ToSlash(path) + ":" + strconv.Itoa(position.Line),
357				keys:  keys,
358			})
359		}
360		return out
361	}
362	
363	func isKeySwitch(clauses []caseClause) bool {
364		for _, clause := range clauses {
365			for _, key := range clause.keys {
366				if structuralKeys[key] ||
367					strings.HasPrefix(key, "ctrl+") ||
368					strings.HasPrefix(key, "alt+") ||
369					strings.HasPrefix(key, "shift+") {
370					return true
371				}
372			}
373		}
374		return false
375	}
376	
377	// isModalSwitch recognizes a confirmation modal's switch by the fact that
378	// it binds y and n in lowercase — which no view does.
379	func isModalSwitch(clauses []caseClause) bool {
380		var yes, no bool
381		for _, clause := range clauses {
382			for _, key := range clause.keys {
383				switch key {
384				case "y":
385					yes = true
386				case "n":
387					no = true
388				}
389			}
390		}
391		return yes && no
392	}
393	
394	func exceptionKeys() []string {
395		out := make([]string, 0, len(exceptions))
396		for _, e := range exceptions {
397			out = append(out, e.Key+" ("+e.Surface+")")
398		}
399		return out
400	}
401	
402	func isLetter(key string) bool {
403		return (key >= "a" && key <= "z") || (key >= "A" && key <= "Z")
404	}
405

