260		// isModal marks a clause belonging to a modal's switch, recognized by
261		// the fact that it binds y and n in lowercase. A modal is a mode, not
262		// a view: it takes over before the view sees anything.
263		isModal bool
264	}
265	
266	// keySwitchClauses returns every key-switch clause from the views.
267	//
268	// A switch is recognized as being about keys when one of its clauses
269	// cites a structural key or a ctrl+/alt+ combination. This is safer than
270	// relying on the name of the tested expression: msg.String() is not the
271	// only form, and a switch on runtime.GOOS or on a severity contains none
272	// of these strings.
273	func keySwitchClauses(t *testing.T) []caseClause {
274		t.Helper()
275	
276		seen := map[string]bool{}
277		var clauses []caseClause
278	
279		for _, root := range scannedTrees {
280			err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
281				if err != nil {
282					return err
283				}
284				if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
285					return nil
286				}
287				// This package declares the vocabulary; it necessarily cites it.
288				if strings.Contains(filepath.ToSlash(path), "internal/ui/keymap/") {
289					return nil
290				}
291				if seen[path] {
292					return nil
293				}
294				seen[path] = true
295	
296				fset := token.NewFileSet()
297				file, err := parser.ParseFile(fset, path, nil, 0)
298				if err != nil {
299					t.Fatalf("parse %s: %v", path, err)
300				}
301	
302				ast.Inspect(file, func(n ast.Node) bool {
303					sw, ok := n.(*ast.SwitchStmt)
304					if !ok || sw.Body == nil {
305						return true
306					}
307					parsed := clausesOf(sw, fset, path)
308					if !isKeySwitch(parsed) {
309						return true
310					}
311					if isModalSwitch(parsed) {
312						for i := range parsed {
313							parsed[i].isModal = true
314						}
315					}
316					clauses = append(clauses, parsed...)
317					return true
318				})
319				return nil
320			})
321			if err != nil {
322				t.Fatalf("walk %s: %v", root, err)
323			}
324		}
325	
326		if len(clauses) == 0 {
327			t.Fatal("no key switch found — the scan is broken, not the code")
328		}
329		return clauses
330	}
331	
332	func clausesOf(sw *ast.SwitchStmt, fset *token.FileSet, path string) []caseClause {
333		var out []caseClause
334		for _, stmt := range sw.Body.List {
335			cc, ok := stmt.(*ast.CaseClause)
336			if !ok || len(cc.List) == 0 {
337				continue
338			}
339			var keys []string
340			for _, expr := range cc.List {
341				lit, ok := expr.(*ast.BasicLit)
342				if !ok || lit.Kind != token.STRING {
343					continue
344				}
345				value, err := strconv.Unquote(lit.Value)
346				if err != nil {
347					continue
348				}
349				keys = append(keys, value)
350			}
351			if len(keys) == 0 {
352				continue
353			}
354			position := fset.Position(cc.Pos())
355			out = append(out, caseClause{
356				where: filepath.ToSlash(path) + ":" + strconv.Itoa(position.Line),
357				keys:  keys,
358			})
359		}
360		return out
361	}
362	
363	func isKeySwitch(clauses []caseClause) bool {
364		for _, clause := range clauses {
365			for _, key := range clause.keys {
366				if structuralKeys[key] ||
367					strings.HasPrefix(key, "ctrl+") ||
368					strings.HasPrefix(key, "alt+") ||
369					strings.HasPrefix(key, "shift+") {
370					return true
371				}
372			}
373		}
374		return false
375	}
376	
377	// isModalSwitch recognizes a confirmation modal's switch by the fact that
378	// it binds y and n in lowercase — which no view does.
379	func isModalSwitch(clauses []caseClause) bool {
380		var yes, no bool
381		for _, clause := range clauses {
382			for _, key := range clause.keys {
383				switch key {
384				case "y":
385					yes = true
386				case "n":
387					no = true
388				}
389			}
390		}
391		return yes && no
392	}
393	
394	func exceptionKeys() []string {
395		out := make([]string, 0, len(exceptions))
396		for _, e := range exceptions {
397			out = append(out, e.Key+" ("+e.Surface+")")
398		}
399		return out
400	}
401	
402	func isLetter(key string) bool {
403		return (key >= "a" && key <= "z") || (key >= "A" && key <= "Z")
404	}
